import {config} from './config.js';
import {summarizeMonth,todayBangkok,totals,transition,validateItems,validatePODate} from './domain.js';
export const configured=Boolean(config.supabaseUrl&&config.publishableKey);
let session=null,profile=null,refreshPromise=null;
const sessionStorageKey='po-the-grands-supabase-session-v1';
function clearSession(){session=null;profile=null;try{globalThis.localStorage?.removeItem(sessionStorageKey);}catch{}}
function saveSession(data){const next={...data,expires_at:data.expires_at||Date.now()/1000+data.expires_in};try{globalThis.localStorage?.setItem(sessionStorageKey,JSON.stringify(next));}catch{throw Error('เบราว์เซอร์บันทึก session ไม่ได้ กรุณาตรวจการตั้งค่าพื้นที่จัดเก็บข้อมูล');}session=next;}
async function request(path,{method='GET',body,auth=true,headers={},timeoutMs=15000}={}){if(auth&&session&&Date.now()/1000>session.expires_at-60)await refresh();let response;try{response=await fetch(config.supabaseUrl.replace(/\/$/,'')+path,{method,headers:{apikey:config.publishableKey,...(auth&&session?{Authorization:`Bearer ${session.access_token}`} :{}),'Content-Type':'application/json',...headers},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(timeoutMs)});}catch{throw Error(path.startsWith('/auth/')?'เชื่อมต่อเพื่อเข้าสู่ระบบไม่ได้หรือหมดเวลารอ กรุณาลองเข้าสู่ระบบอีกครั้ง':'เชื่อมต่อไม่ได้หรือหมดเวลารอ กรุณาลองอีกครั้งด้วยคำขอเดิมเพื่อป้องกันรายการซ้ำ');}const data=await response.json().catch(()=>null);if(!response.ok){if(response.status===401||(path.includes('grant_type=refresh_token')&&response.status===400)){clearSession();throw Object.assign(Error('หมดเวลาเข้าสู่ระบบ กรุณาเข้าสู่ระบบอีกครั้ง ข้อมูลที่กรอกยังอยู่'),{authExpired:true});}throw Error(data?.message||data?.msg||data?.error_description||'บันทึกไม่ได้ กรุณาลองอีกครั้ง');}return {data,response};}
async function refresh(){if(!session)throw Error('กรุณาเข้าสู่ระบบ');if(!refreshPromise)refreshPromise=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',auth:false,body:{refresh_token:session.refresh_token}}).then(r=>saveSession(r.data)).finally(()=>{refreshPromise=null;});await refreshPromise;}
export const api={
 async login(username,password){const entered=String(username||'').trim().toLowerCase();const options=entered.includes('@')?{path:'/auth/v1/token?grant_type=password',body:{email:entered,password}}:{path:'/functions/v1/owner-account',body:{action:'login',username:entered,password}};const {data}=await request(options.path,{method:'POST',auth:false,body:options.body,timeoutMs:45000});saveSession(data);const p=await request('/rest/v1/profiles?id=eq.'+encodeURIComponent(data.user.id)+'&select=id,role,display_name,login_email,login_name,can_export_report',{timeoutMs:45000});if(!p.data?.length){clearSession();throw Error('บัญชีนี้ยังไม่ได้รับสิทธิ์ใช้งาน กรุณาติดต่อเจ้าของ');}profile=p.data[0];return profile;},
 async updateOwnerLoginName({username,currentPassword}){const {data}=await request('/functions/v1/owner-account',{method:'POST',body:{action:'update-login-name',username,currentPassword},timeoutMs:45000});profile={...profile,...data.user};return profile;},
 async changeOwnerPassword({currentPassword,newPassword}){const {data}=await request('/functions/v1/owner-account',{method:'POST',body:{action:'change-password',currentPassword,newPassword},timeoutMs:45000});clearSession();return data;},
 async restoreSession(){let saved;try{saved=globalThis.localStorage?.getItem(sessionStorageKey);}catch{throw Error('อ่าน session จากเบราว์เซอร์ไม่ได้ กรุณาตรวจการตั้งค่าพื้นที่จัดเก็บข้อมูล');}if(!saved)return null;try{session=JSON.parse(saved);if(!session?.access_token||!session?.refresh_token||!session?.user?.id||!Number.isFinite(Number(session.expires_at)))throw Error('invalid session');}catch{clearSession();return null;}try{if(Date.now()/1000>session.expires_at-60)await refresh();const p=await request('/rest/v1/profiles?id=eq.'+encodeURIComponent(session.user.id)+'&select=id,role,display_name,login_email,login_name,can_export_report');if(!p.data?.length){clearSession();return null;}profile=p.data[0];return profile;}catch(e){if(e.authExpired){clearSession();return null;}throw e;}},
 async logout(){try{if(session)await request('/auth/v1/logout',{method:'POST'});}finally{clearSession();}},
 async list(status,page=1,scope='all'){const own=profile?.role==='office'&&(!profile.can_export_report||scope==='mine');const query=`select=*&order=po_date.desc,created_at.desc&limit=10&offset=${(page-1)*10}`+(status?`&status=eq.${encodeURIComponent(status)}`:'')+(own?`&created_by=eq.${encodeURIComponent(profile.id)}`:'');const {data,response}=await request('/rest/v1/purchase_orders?'+query,{headers:{Prefer:'count=exact'}});return {rows:data,total:Number(response.headers.get('content-range')?.split('/')[1]||0)};},
 async stats(scope='all'){const own=profile?.role==='office'&&(!profile.can_export_report||scope==='mine');return (await request('/rest/v1/rpc/po_counts',{method:'POST',body:{p_mine:own}})).data;},
 async detail(id){const {data}=await request('/rest/v1/purchase_orders?id=eq.'+encodeURIComponent(id)+'&select=*');if(!data?.length)throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');const events=await request('/rest/v1/po_events?po_id=eq.'+encodeURIComponent(id)+'&select=*&order=at.asc');return {...data[0],events:events.data};},
 async create(items,po_date,key,department){return (await request('/rest/v1/rpc/create_po',{method:'POST',body:{p_items:items,p_po_date:po_date,p_request_id:key,p_department:department}})).data;},
 async action(po,action,reason,confirmed,key){return (await request('/rest/v1/rpc/act_on_po',{method:'POST',body:{p_id:po.id,p_action:action,p_version:po.version,p_reason:reason,p_invoice_confirmed:confirmed,p_request_id:key}})).data;},
 async report(month){return (await request('/rest/v1/rpc/monthly_po_report',{method:'POST',body:{p_month:month+'-01'}})).data;},
 async departments(){const {data}=await request('/rest/v1/departments?select=name&archived_at=is.null&order=name.asc');return data.map(row=>row.name);},
 async addDepartment(name){return request('/rest/v1/rpc/manage_department',{method:'POST',body:{p_action:'add',p_name:name}});},
 async archiveDepartment(name){return request('/rest/v1/rpc/manage_department',{method:'POST',body:{p_action:'archive',p_name:name}});},
 async notifications(){return (await request('/rest/v1/notifications?select=*&order=created_at.desc&limit=100')).data;},
 async markNotificationsRead(){return request('/rest/v1/notifications?read_at=is.null',{method:'PATCH',body:{read_at:new Date().toISOString()},headers:{Prefer:'return=minimal'}});},
 async users(){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'list'}})).data.users;},
 async saveOffice(account){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'upsert',...account}})).data.user;},
 async deleteUser(account){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'delete',profile_id:account.id}})).data.user;}
};

const demoStorage='po-the-grands-demo-accounts-v1';
const toHex=bytes=>[...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');
async function hashPassword(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return toHex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256));}
function demoAccounts(){try{return JSON.parse(localStorage.getItem(demoStorage)||'[]');}catch{return [];}}
function saveDemoAccounts(accounts){localStorage.setItem(demoStorage,JSON.stringify(accounts));}
export const demoAuth={
 needsSetup(){return demoAccounts().length===0;},
 async setupOwner(password){if(!this.needsSetup())throw Error('ตั้งค่าบัญชีเจ้าของแล้ว');if(password.length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID(),password_hash=await hashPassword(password,salt);const owner={id:'demo-owner',username:'owner',display_name:'เจ้าของ',role:'owner',salt,password_hash};saveDemoAccounts([owner]);return {...owner,password_hash:undefined,salt:undefined};},
 async resetOwner(password){if(password.length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const accounts=demoAccounts(),owner=accounts.find(a=>a.role==='owner'||a.username==='owner');if(!owner)throw Error('ยังไม่มีบัญชีเจ้าของ');const salt=crypto.randomUUID(),password_hash=await hashPassword(password,salt);Object.assign(owner,{salt,password_hash});saveDemoAccounts(accounts);return {id:owner.id,username:owner.username,display_name:owner.display_name,role:owner.role};},
 async login(username,password){const normalized=String(username).trim().toLowerCase();const account=demoAccounts().find(a=>a.username.toLowerCase()===normalized||a.display_name.toLowerCase()===normalized);if(!account||await hashPassword(password,account.salt)!==account.password_hash)throw Error('ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง — ใช้ชื่อบัญชีที่เจ้าของกำหนด');return {id:account.id,username:account.username,display_name:account.display_name,role:account.role,can_export_report:account.can_export_report===true||account.username==='purchase.fai01'};},
 list(actor){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');return demoAccounts().filter(a=>a.role==='office').map(({password_hash,salt,...a})=>({...a,can_export_report:a.can_export_report===true||a.username==='purchase.fai01'}));},
 async saveOffice(actor,{username,display_name,password}){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');username=String(username||'').trim().toLowerCase();display_name=String(display_name||'').trim();if(!/^[a-z0-9._-]{3,50}$/.test(username))throw Error('ชื่อผู้ใช้ใช้ a-z, 0-9, จุด ขีด และขีดล่าง 3–50 ตัว');if(!display_name||display_name.length>100)throw Error('ระบุชื่อที่แสดงไม่เกิน 100 ตัวอักษร');const accounts=demoAccounts(),existing=accounts.find(a=>a.username===username);if(password==='__KEEP__')password='';if(!existing&&String(password||'').length<8)throw Error('บัญชีใหม่ต้องมีรหัสผ่านอย่างน้อย 6 ตัวอักษร');let next={id:existing?.id||crypto.randomUUID(),username,display_name,role:'office'};if(password){if(String(password).length<8)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID();next={...next,salt,password_hash:await hashPassword(password,salt)};}else next={...existing,...next};const index=existing?accounts.indexOf(existing):-1;if(index>=0)accounts[index]=next;else accounts.push(next);saveDemoAccounts(accounts);return {id:next.id,username,display_name,role:'office'};}
};

export function makeDemo(){const office={id:'demo-office',role:'office',display_name:'ออฟฟิศ'};const samples=[['กระดาษถ่ายเอกสาร A4','80 แกรม ขนาด A4 บรรจุ 500 แผ่น / รีม','ร้านเครื่องเขียนเชียงใหม่','10','214',true,'pending'],['อุปกรณ์สำนักงาน','ปากกาลูกลื่นสีน้ำเงิน บรรจุ 12 ด้าม / กล่อง','ห้างค้าส่ง','4','214',true,'pending'],['หมึกเครื่องพิมพ์','ตลับหมึกสีดำ รุ่น 85A','ตัวแทนจำหน่าย HP','2','1605',true,'approved'],['ชั้นจัดเก็บเอกสาร','ชั้นเหล็ก 4 ชั้น ขนาด 90 × 45 × 180 ซม.','ร้านเฟอร์นิเจอร์สำนักงาน','1','4815',true,'received'],['กล่องจัดเก็บเอกสาร','กล่องกระดาษแข็ง ขนาด A4','ร้านเครื่องเขียนเชียงใหม่','6','100',false,'closed']];let rows=samples.map((s,n)=>{const items=validateItems([{name:s[0],spec:s[1],source:s[2],note:'',qty:s[3],unit_price:s[4],vat:s[5]}]);let p={id:crypto.randomUUID(),po_number:'DEMO-2026-'+String(5-n).padStart(5,'0'),po_date:new Date(Date.now()-n*86400000).toISOString().slice(0,10),created_at:new Date(Date.now()-n*86400000).toISOString(),created_by:office.id,requester_name:office.display_name,status:'pending',items,...totals(items),version:1,events:[{action:'create',actor_name:office.display_name,at:new Date(Date.now()-n*86400000).toISOString()}]};if(n>=2)p=transition(p,'approve',{role:'owner',display_name:'เจ้าของ'});if(n>=3)p=transition(p,'receive',office);if(n>=4)p=transition(p,'close',{role:'owner',display_name:'เจ้าของ'},'',true);return p;});try{const stored=JSON.parse(localStorage.getItem('po-the-grands-demo-orders-v1')||'[]');if(Array.isArray(stored))rows.push(...stored);}catch{}const persist=()=>localStorage.setItem('po-the-grands-demo-orders-v1',JSON.stringify(rows.filter(row=>row.created_by!=='demo-office')));const commands=new Map();return {async list(status,page=1){const result=rows.filter(r=>!status||r.status===status);return {rows:result.slice((page-1)*10,page*10),total:result.length};},async departments(){const key='po-the-grands-demo-departments-v1',fallback=['อาหาร','ของหวาน','ผลไม้','ติ่มซำ','แซนวิช','สลัด','ครัวกลาง','แม่บ้าน','ออฟฟิศ','ช่าง','ภูดอย','บ้านโจ้','ท่ารั้ว'];try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}},async stats(){return Object.fromEntries(['pending','approved','received','closed','rejected'].map(s=>[s,rows.filter(r=>r.status===s).length]));},async detail(id){return structuredClone(rows.find(r=>r.id===id));},async create(items,po_date,key,actor,department){if(commands.has(key))return commands.get(key);const normalized=validateItems(items),now=new Date().toISOString();const p={id:crypto.randomUUID(),po_number:'DEMO-2026-'+String(rows.length+1).padStart(5,'0'),po_date:validatePODate(po_date),created_at:now,created_by:actor.id,requester_name:actor.display_name,department:department||'',status:'pending',items:normalized,...totals(normalized),version:1,events:[{action:'create',actor_name:actor.display_name,at:now}]};rows.unshift(p);persist();commands.set(key,p);return p;},async action(po,action,reason,confirmed,key,currentActor){if(commands.has(key))return commands.get(key);const ix=rows.findIndex(r=>r.id===po.id);if(rows[ix].version!==po.version)throw Error('สถานะเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');rows[ix]=transition(rows[ix],action,currentActor,reason,confirmed);persist();commands.set(key,rows[ix]);return rows[ix];},async report(month){return summarizeMonth(rows.filter(r=>r.po_date.startsWith(month)));},async users(actor){return demoAuth.list(actor);},async saveOffice(account,actor){return demoAuth.saveOffice(actor,account);}};}
demoAuth.saveOffice=async function(actor,{username,display_name,password,id,can_export_report}){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');username=String(username||'').trim();display_name=String(display_name||'').trim();if(!/^[a-z0-9._]{4,50}$/.test(username.toLowerCase()))throw Error('ชื่อผู้ใช้ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง 4–50 ตัว');username=username.toLowerCase();if(!display_name||display_name.length>100)throw Error('ระบุชื่อที่แสดงไม่เกิน 100 ตัวอักษร');const accounts=demoAccounts(),existing=id?accounts.find(a=>a.id===id):accounts.find(a=>a.username===username);if(password==='__KEEP__')password='';if(!existing&&String(password||'').length<6)throw Error('บัญชีใหม่ต้องใช้รหัสผ่านอย่างน้อย 6 ตัวอักษร');let next={...existing,id:existing?.id||crypto.randomUUID(),username,display_name,role:'office',can_export_report:can_export_report===true||username==='purchase.fai01'};if(password){if(String(password).length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID();next={...next,salt,password_hash:await hashPassword(password,salt)};}const index=existing?accounts.indexOf(existing):-1;if(index>=0)accounts[index]=next;else accounts.push(next);saveDemoAccounts(accounts);return {id:next.id,username,display_name,role:'office',can_export_report:next.can_export_report};};
demoAuth.deleteUser=async function(actor,target){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');if(!target?.id||target.role!=='office')throw Error('ไม่สามารถลบบัญชีนี้ได้');const accounts=demoAccounts(),index=accounts.findIndex(a=>a.id===target.id);if(index<0)throw Error('ไม่พบบัญชีที่ต้องการลบ');accounts.splice(index,1);saveDemoAccounts(accounts);return {id:target.id};};
